mapper.insert:
INSERT INTO genre_character (user_id, genre_character_group_id, name)
SELECT e.user_id, e.genre_character_group_id, #{defaultName}
FROM genre_character_group e
JOIN template_genre_character_group g ON g.name = e.name AND g.template_id = #{templateId}
WHERE e.user_id = #{userId}
  AND NOT EXISTS (
      SELECT 1 FROM genre_character c
      WHERE c.user_id = e.user_id AND c.genre_character_group_id = e.genre_character_group_id AND c.name = #{defaultName}
  )
